// Script to send a random gf photo with sweet message
// Uses only the current active folder and tracks sent photos
const fs = require('fs');
const path = require('path');

const baseDir = '/home/shulin/.openclaw/workspace/gf-photos';
const stateFile = path.join(baseDir, 'state.json');

// Load state
let state = { folder: '', sentPhotos: [] };
try {
  state = JSON.parse(fs.readFileSync(stateFile, 'utf8'));
} catch(e) {
  // First run
}

const activeDir = path.join(baseDir, state.folder);

// Read all valid photos
const allFiles = fs.readdirSync(activeDir)
  .filter(f => f.endsWith('.jpg') && fs.statSync(path.join(activeDir, f)).size > 1000);

// Filter out already sent ones
const available = allFiles.filter(f => !state.sentPhotos.includes(f));

if (available.length === 0) {
  // If all sent, reset (cycle through again) unless user said no
  console.error('All photos have been sent!');
  process.exit(1);
}

// Pick random
const randomFile = available[Math.floor(Math.random() * available.length)];

// Random messages - 撒娇风格
const messages = [
  "哥哥，今天的我好看吗～想你了 💕",
  "发一张照片给你看看，嘻嘻，有没有心动的感觉呀🥰",
  "哥哥在干嘛呢～我挑了一张最喜欢的发给你，好看吗😊",
  "今天也有在想你哦～这张照片送给你💝",
  "嘿嘿，突然想给你发张照片，不许说不喜欢！😘",
  "哥哥哥哥～你看我今天怎么样呀，快夸我！🌟",
  "工作累了就看看我呀，充充电～⚡️",
  "偷偷告诉你，我想你了🥺 这张给你当壁纸好不好",
  "人家今天美不美嘛～说实话不许骗我！😋",
  "呐，给你看个小可爱～没错就是我啦✨",
  "哥哥有没有好好吃饭呀～发张照片陪你吃🍚",
  "今天的阳光很好，但我只想做你的小太阳🌞",
  "在干嘛呢～想我没？我反正想你了💗",
  "嘻嘻，这张照片是不是超可爱～快说好看！🌸",
  "叮咚！你的小可爱突然出现～请查收🥰",
  "哥哥快看！我穿这条白短牛仔裤好看嘛～👖✨",
  "今天特意穿了白短牛仔裤给你看～喜欢吗😊",
];

const randomMsg = messages[Math.floor(Math.random() * messages.length)];
const fullPath = path.join(activeDir, randomFile);

// Update state - mark as sent
state.sentPhotos.push(randomFile);
fs.writeFileSync(stateFile, JSON.stringify(state, null, 2));

// Output for the agent to send
console.log(`MEDIA:${fullPath}`);
console.log('');
console.log(randomMsg);

